#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7
REPO="richardkabiling/loop-test-repo"
GH_OK=0
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then GH_OK=1; fi

banner "Charmander loop: human-only setup for $REPO"
(( GH_OK )) || warn "gh is missing or not signed in: stages fall back to manual steps (run 'gh auth login' first for the fast path)."

# ── 1. main as the default branch ─────────────────────────────────────────
stage "Create main and make it the default branch"
say "Merge to main deploys everything, so main must exist and be the default branch."
note "main starts at the repo's first commit; the loop setup then lands on main through a reviewed PR."
if (( GH_OK )) && gh api "repos/$REPO/branches/main" >/dev/null 2>&1; then
  say "✓ main already exists."
elif (( GH_OK )) && confirm "Create main at the repo's first commit?"; then
  ROOT_SHA=$(git rev-list --max-parents=0 HEAD | tail -n1)
  gh api "repos/$REPO/git/refs" -f ref=refs/heads/main -f sha="$ROOT_SHA" >/dev/null && say "✓ created main at $ROOT_SHA"
else
  SKIPPED+=("create branch main")
fi
if (( GH_OK )) && confirm "Set main as the default branch?"; then
  gh api -X PATCH "repos/$REPO" -f default_branch=main >/dev/null && say "✓ default branch is main"
else
  open_url "https://github.com/$REPO/settings"
  step "Settings → General → Default branch → switch to main → Update."
  pause "Done?"
fi
pause

# ── 2. Ruleset on main ────────────────────────────────────────────────────
stage "Protect main (the deploy gate)"
say "Ruleset 'main: deploy gate': PR required, 1 approval minimum, approval from someone other"
say "than the last pusher, stale approvals dismissed, conversations resolved, no force push or deletion."
note "Critical-tier PRs need 2 approvals: /charmander-review requests them and pr-checks.sh checks the tier label."
if (( GH_OK )) && gh api "repos/$REPO/rulesets" --jq '.[].name' 2>/dev/null | grep -qx "main: deploy gate"; then
  say "✓ ruleset already exists."
elif (( GH_OK )) && confirm "Create the ruleset now via the GitHub API?"; then
  gh api -X POST "repos/$REPO/rulesets" --input - >/dev/null <<'JSON' && say "✓ ruleset created" || { warn "API call failed"; SKIPPED+=("ruleset on main"); }
{
  "name": "main: deploy gate",
  "target": "branch",
  "enforcement": "active",
  "conditions": { "ref_name": { "include": ["~DEFAULT_BRANCH"], "exclude": [] } },
  "rules": [
    { "type": "deletion" },
    { "type": "non_fast_forward" },
    { "type": "pull_request", "parameters": {
        "required_approving_review_count": 1,
        "dismiss_stale_reviews_on_push": true,
        "require_code_owner_review": false,
        "require_last_push_approval": true,
        "required_review_thread_resolution": true
    } }
  ]
}
JSON
else
  open_url "https://github.com/$REPO/settings/rules"
  step "New ruleset → New branch ruleset → name 'main: deploy gate' → Enforcement: Active."
  step "Target branches → Add target → Include default branch."
  step "Tick: Restrict deletions, Block force pushes, Require a pull request before merging."
  step "Under the PR rule: 1 approval, Dismiss stale approvals, Require approval of the most recent push, Require conversation resolution."
  pause "Saved?"
fi
pause

# ── 3. Labels ─────────────────────────────────────────────────────────────
stage "Create the loop's labels"
LABELS="tier:critical|b60205|PR tier: 2 approvals, extra lenses
tier:standard|fbca04|PR tier: 1 approval
tier:low|0e8a16|PR tier: docs only, 1 approval
epic|5319e7|Work item: intent + design live here
intent-approved|1d76db|Intent gate passed
design-approved|1d76db|Design gate passed
ready-for-agent|0052cc|Executable acceptance criteria; may run unattended
ready-for-human|c5def5|Needs a human to build
needs-triage|ededed|Not triaged yet
needs-info|d4c5f9|Waiting for information
wontfix|ffffff|Will not be done
test-change-approved|e99695|Human approved changing an existing test"
if (( GH_OK )); then
  while IFS='|' read -r name color desc; do
    gh label create "$name" --repo "$REPO" --color "$color" --description "$desc" --force >/dev/null && step "✓ $name"
  done <<<"$LABELS"
else
  open_url "https://github.com/$REPO/labels"
  say "Create each label:"; while IFS='|' read -r name _ _; do step "$name"; done <<<"$LABELS"
  pause "Done?"
fi
pause

# ── 4. Secret scanning ────────────────────────────────────────────────────
stage "Secret scanning and push protection"
if (( GH_OK )) && confirm "Turn on secret scanning + push protection via the API?"; then
  if gh api -X PATCH "repos/$REPO" --input - >/dev/null 2>&1 <<'JSON'
{ "security_and_analysis": { "secret_scanning": { "status": "enabled" }, "secret_scanning_push_protection": { "status": "enabled" } } }
JSON
  then say "✓ enabled"
  else warn "API refused (private repos may need GitHub Secret Protection). Do it in the browser:"; open_url "https://github.com/$REPO/settings/security_analysis"; pause "Done?"; fi
else
  open_url "https://github.com/$REPO/settings/security_analysis"
  step "Enable Secret scanning, then Push protection."
  pause "Done?"
fi
(( GH_OK )) && gh api "repos/$REPO" --jq '.security_and_analysis // "not reported"' 2>/dev/null | sed 's/^/  /' || true
pause

# ── 5. lefthook ───────────────────────────────────────────────────────────
stage "Git hooks (lefthook)"
say "Runs protect-paths and diff-guard on every commit, for every tool and human."
if ! command -v lefthook >/dev/null 2>&1; then
  step "Install lefthook: macOS 'brew install lefthook' · any OS 'npm i -g lefthook' · Go 'go install github.com/evilmartians/lefthook@latest'"
  pause "Installed?"
fi
if command -v lefthook >/dev/null 2>&1; then
  lefthook install && say "✓ hooks installed"
else
  SKIPPED+=("lefthook install")
fi
pause

# ── 6. Cursor + Codex skills ──────────────────────────────────────────────
stage "Skills for Cursor and Codex"
say "Claude Code already has mattpocock-skills (project plugins). Cursor and Codex need their own copy."
if confirm "Run 'npx skills@latest add mattpocock/skills -a cursor -a codex' now?"; then
  npx --yes skills@latest add mattpocock/skills -a cursor -a codex || { warn "install failed"; SKIPPED+=("mattpocock skills for Cursor/Codex"); }
else
  SKIPPED+=("npx skills@latest add mattpocock/skills -a cursor -a codex")
fi
pause

# ── 7. Metals MCP ─────────────────────────────────────────────────────────
stage "Scala code intelligence (Metals MCP)"
say "Metals writes its own MCP config for your editor once its MCP server is on."
step "Open backend/ in VS Code or Cursor with the Metals extension (Metals 1.5+)."
step "Settings → search 'metals.startMcpServer' → enable it, then reload the window."
step "Metals adds its server entry to the editor's MCP config; for Claude Code, add the same URL to .mcp.json."
open_url "https://scalameta.org/metals/docs/editors/user-configuration"
pause "Done (or skip for now)?"

finish
}

run_wizard "$@"; exit
